1253:     if (targetImage) return this.resolveImageReference(targetImage, context);
1254:     if (required)
1255:       throw new Error(
1256:         "Image editing requires --source <asset-id|app-url|file|data-url>, or a target that already has an image.",
1257:       );
1258:     return null;
1259:   }
