1261:   private findSprite(ownerId: string, expression: string) {
1262:     spriteFolder(ownerId);
1263:     const sprites = listSpriteCatalog(ownerId).sprites;
1264:     const exact = sprites.find((sprite) => sprite.expression === expression);
1265:     const matches = sprites.filter((sprite) => sprite.label === expression);
1266:     if (!exact && matches.length > 1) throw new Error("More than one sprite has that label; use its file handle.");
1267:     return exact ?? matches[0];
1268:   }
