1270:   private async currentImageReferenceForTarget(target: ImageTarget): Promise<string | null> {
1271:     const characters = createCharactersStorage(this.db);
1272:     switch (target.type) {
1273:       case "character-avatar": {
1274:         const row = await characters.getById(target.characterId);
1275:         if (!row) throw new Error(`Character not found: ${target.characterId}`);
1276:         return row.avatarPath ?? null;
1277:       }
1278:       case "persona-avatar": {
1279:         const row = await characters.getPersona(target.personaId);
1280:         if (!row) throw new Error(`Persona not found: ${target.personaId}`);
1281:         return row.avatarPath ?? null;
1282:       }
1283:       case "lorebook-image": {
1284:         const row = await createLorebooksStorage(this.db).getById(target.lorebookId);
1285:         if (!row) throw new Error(`Lorebook not found: ${target.lorebookId}`);
1286:         return typeof row.imagePath === "string" ? row.imagePath : null;
1287:       }
1288:       case "sprite": {
1289:         return this.findSprite(target.ownerId, target.expression)?.url ?? null;
1290:       }
1291:       case "background":
1292:         return target.filename ? `/api/backgrounds/file/${encodeURIComponent(target.filename)}` : null;
1293:       case "chat-gallery":
1294:         if (!target.imageId) return null;
1295:         return this.chatGalleryImageUrl(target.chatId, target.imageId);
1296:       case "character-gallery":
1297:         if (!target.imageId) return null;
1298:         return this.characterGalleryImageUrl(target.characterId, target.imageId);
1299:       case "asset":
1300:         return target.assetId ?? null;
1301:       case "theme-image": {
1302:         const theme = await createThemesStorage(this.db).getById(target.themeId);
1303:         if (!theme) throw new Error(`Theme not found: ${target.themeId}`);
1304:         return theme.meta?.images?.find((image) => image.name === target.name)?.src ?? null;
1305:       }
1306:     }
1307:   }
