1324:   private async resolveImageReference(value: string, context: ImageCommandContext): Promise<ResolvedImage> {
1325:     const data = decodeDataImage(value);
1326:     if (data) return data;
1327: 
1328:     const assets = await readManifest();
1329:     const asset = assets.find(
1330:       (candidate) =>
1331:         candidate.id === value ||
1332:         candidate.filename === value ||
1333:         candidate.url === value ||
1334:         candidate.filePath === value,
1335:     );
1336:     if (asset) {
1337:       const image = await imageFromFile(
1338:         assertInsideDir(PREVIEW_DIR, join(PREVIEW_DIR, asset.filename)),
1339:         `asset:${asset.id}`,
1340:         PREVIEW_DIR,
1341:       );
1342:       return { ...image, url: asset.url, asset };
1343:     }
